\copy (SELECT m.musteri_kodu AS kod, m.musteri_adi AS ad, m.vergi_no AS vkn, m.vergi_dairesi AS vd, m.sehir AS sehir, m.satis_kanali AS kanal, r.grup AS grup FROM master_musteri m JOIN (SELECT DISTINCT ON (muhatap_kodu) muhatap_kodu, grup FROM bi_musteri_risk WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND musteri_mi ORDER BY muhatap_kodu, export_date DESC NULLS LAST) r ON r.muhatap_kodu=m.musteri_kodu WHERE m.tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND r.grup IN ('FILO TICARI','TOPTAN','KURUM','IMALATCI','IHRACAT','GRUP MUSTERILERI') ORDER BY m.musteri_kodu) TO STDOUT WITH CSV HEADER
